// Velure — validate a Book button the assistant wants to show.
// The website only renders a button for an action that passed this check.
const TREATMENTS = {
  'signature-glow-facial': 'Signature Glow Facial',
  'wrinkle-relaxers': 'Wrinkle Relaxers',
  'dermal-fillers': 'Dermal Fillers',
  'collagen-microneedling': 'Collagen Microneedling',
  'laser-rejuvenation': 'Laser Rejuvenation',
  'body-contouring': 'Body Contouring',
  'consultation': 'Consultation',
};
const SLOTS = ['09:00','09:30','10:00','10:30','11:00','11:30','12:00','12:30','13:00','13:30',
  '14:00','14:30','15:00','15:30','16:00','16:30','17:00','17:30','18:00'];

const PHX_OFFSET_MS = 7 * 3600 * 1000;
const ymd = (d) => d.toISOString().slice(0, 10);
const addDays = (key, n) => {
  const [y, m, d] = key.split('-').map(Number);
  return ymd(new Date(Date.UTC(y, m - 1, d + n)));
};
const isSunday = (key) => new Date(key + 'T12:00:00Z').getUTCDay() === 0;
const today = ymd(new Date(Date.now() - PHX_OFFSET_MS));
const min = addDays(today, 1);
const max = addDays(today, 60);

const j = $input.first().json;
const s = (v) => (v === null || v === undefined ? '' : String(v).trim());
const empty = (v) => ['', 'null', 'none', 'undefined', 'n/a'].includes(v.toLowerCase());

const treatmentId = s(j.treatmentId).toLowerCase();
let date = s(j.date);
let time = s(j.time);
if (empty(date)) date = '';
if (empty(time)) time = '';
if (/^\d:\d{2}$/.test(time)) time = '0' + time;

if (!TREATMENTS[treatmentId]) {
  return [{ json: { ok: false, error: `Unknown treatmentId "${treatmentId}". Use one of: ${Object.keys(TREATMENTS).join(', ')}.` } }];
}

const notes = [];
if (date && (!/^\d{4}-\d{2}-\d{2}$/.test(date) || date < min || date > max || isSunday(date))) {
  notes.push(`Date ${date} cannot be booked online (${min} to ${max}, Monday to Saturday), so the button opens without a date.`);
  date = '';
}
if (time && !SLOTS.includes(time)) {
  notes.push(`Time ${time} is not a start time, so the button opens without a time.`);
  time = '';
}
if (time && !date) {
  notes.push('A time without a date was dropped.');
  time = '';
}

return [{ json: {
  ok: true,
  action: { type: 'book', treatmentId, date: date || null, time: time || null },
  message: 'A Book button is now shown under your reply. The visitor finishes the booking in the panel.',
  notes: notes.join(' '),
} }];
